import sys
import copy
from collections import deque,defaultdict
import math
import heapq
from itertools import accumulate
import itertools 
from functools import reduce
#import pypyjit
#pypyjit.set_param('max_unroll_recursion=-1')
sys.setrecursionlimit(10**8)
mod = 10**9 + 7
INF = math.inf
input = lambda: sys.stdin.readline().rstrip()
ii = lambda: int(input())
mi = lambda: map(int, input().split())
li = lambda: list(mi())
from functools import lru_cache #@lru_cache(maxsize=None)

def euler_phi(n):
    res = n
    temp_n = n
    for x in range(2,int(math.sqrt(n))+1):
        if temp_n%x==0:
            res = res//x * (x-1)
            while temp_n%x==0:
                temp_n //= x
    if temp_n!=1:
        res = res//temp_n * (temp_n-1)
    return res

def divisors(n):
    lower_divisors, upper_divisors = [], []
    i = 1
    while i * i <= n:
        if n % i == 0:
            lower_divisors.append(i)
            if i != n // i:
                upper_divisors.append(n // i)
        i += 1
    return sorted(lower_divisors + upper_divisors[::-1])

def calc(K:int)->int:
    if K == 1:
        return 1

    # Remove factors of 2 and 5
    while K % 2 == 0:
        K //= 2
    while K % 5 == 0:
        K //= 5

    # If K became 1, no periodic part (or purely non-repeating decimal)
    if K == 1:
        return 1

    # Check if gcd(K, 10) == 1 (should be true now)
    if math.gcd(K, 10) != 1:
        return -1

