        print('Bob')
        return

    if len(B) % 2 == 0 and M % 2 == 0:
        B = sorted(B)
        C, D = B[:len(B)//2], B[len(B)//2:]

        for c, d in zip(C, D):
            if c % (M // 2) != d % (M // 2):
                print('Alice')
                return
        print('Bob')
        return

    print('Alice')


