inf=10**9
def solve():
    n,h=MII()
    A=LII()
    B=[LII() for i in range(n-1)]+[[0,0]]
    dp=[[inf]*(h+1) for i in range(h+1)]
    for i in range(h+1):
        dp[h][i]=0
    pre=0
    for k in range(n):
        p,f=B[k]
        x=A[k]-pre
        pre=A[k]
        ndp=[[inf]*(h+1) for i in range(h+1)]
        for i in range(h+1):
            for j in range(h+1):
                if x<=i and j+x<=h:
                    ndp[i-x][j+x]=min(ndp[i-x][j+x],dp[i][j])
                if i>=x and j+x<=h:
                    ndp[min(i-x+f,h)][j+x] = min(ndp[min(i-x+f,h)][j+x], p+dp[i][j])
                if i+x<=h and j>=x and j+f-x<=h:
                    ndp[i+x][j+f-x] = min(ndp[i+x][j+f-x], p+dp[i][j])
        dp=ndp[:]


    ans=inf
    for i in range(h+1):
        ans=min(dp[i][i],ans)
    if ans<inf:
        print(ans)
    else:
        print(-1)


for _ in range(1):
    solve()

