def LGMI():
    return list(map(lambda x: int(x) - 1, input().split()))

inf=10**9
def solve():
    n,h=MII()
    A=LII()
    B=[]
    for i in range(n-1):
        B.append(LII())
    B.append([0,0])
    dp=[[inf]*(h+1) for i in range(h+1)]
    for i in range(h+1):
        dp[h][i]=0
    pre=0
    for k in range(n):
        p,f=B[k]
        x=A[k]-pre
        pre=A[k]
        ndp=[[inf]*(h+1) for i in range(h+1)]
        for i in range(h+1):
            for j in range(h+1):
                if dp[i][j] < inf:
                    if x<=i and j+x<=h:
                        ndp[i-x][j+x]=min(ndp[i-x][j+x],dp[i][j])
                    if i>=x and j+x<=h:
                        ndp[min(i-x+f,h)][j+x] = min(ndp[min(i-x+f,h)][j+x], p+dp[i][j])
                    if i+x<=h and j>=x:
                        ndp[i][j-x+min(f,h)] = min(ndp[i][j-x+min(f,h)], p+dp[i][j])
        dp=ndp


    ans=inf
    for i in range(h+1):
        ans=min(dp[i][i],ans)
    if ans<inf:
        print(ans)
    else:
        print(-1)


for _ in range(1):
    solve()

