def solve():
    n, x, k = list(map(int, input().split(' ')))
    n += 1
    k = min(100, k)
    ans = 0

    for depth in range(k, -1, -1):
        if depth == k:
            L = x * (1 << depth)
            R = L + (1 << depth)
        else:
            bit_pos = depth
            if (x >> (k - depth)) & 1:
                L = ((x >> (k - depth - 1)) ^ 1) << (depth + 1)
            else:
                L = ((x >> (k - depth - 1)) ^ 1) << (depth + 1)
            L = ((x >> (k - depth)) ^ 1) << depth
            R = L + (1 << depth)

        intersection = max(0, min(R, n) - max(0, L))
        ans += intersection

    return ans

