    n = len(A)
    L = [0] * n
    for i, a in enumerate(A):
        for j, b in enumerate(B):
            ij = min(i + j, n - 1)
            L[ij] = (L[ij] + a * b) % P
    return L

def power(A, k):
    if k == 1:
        return A
    if k % 2 == 0:
        return power(mult(A, A), k // 2)
    return mult(power(A, k - 1), A)


