def solve():
    n=int(input())
    A=list(map(int,input().split()))
    l1,c1,k1=map(int,input().split())
    l2,c2,k2=map(int,input().split())

    # dp[i][j] = True if we can use exactly i units of resource 1 and j units of resource 2
    dp=[[False]*(k2+1) for _ in range(k1+1)]
    dp[0][0]=True

    for a in A:
        new_dp=[[False]*(k2+1) for _ in range(k1+1)]
        d1=(a+l1-1)//l1  # max units of resource 1 needed

        for x in range(d1+1):
            y=(a-l1*x+l2-1)//l2  # units of resource 2 needed
            if y<0:
                y=0
            if y>k2:
                continue

            for nx in range(k1+1):
                for ny in range(k1+1):
                    if dp[nx][ny] and nx+x<=k1 and ny+y<=k2:
                        new_dp[nx+x][ny+y]=True

        dp=new_dp

    ans=10**20
    found=False
    for i in range(k1+1):
        for j in range(k2+1):
            if dp[i][j]:
                found=True
                ans=min(ans,i*c1+j*c2)

    if not found:
        print(-1)
    else:
        print(ans)

