    # r = int(p**0.5) + 1, fr:f^r
    if a == b:
        return 0
    # baby step
    baby = {}
    current = b
    for i in range(r):
        if current not in baby:
            baby[current] = i
        current = f(current)
    # giant step
    current = a
    for j in range(1, r + 3):
        current = fr(current)
        if current in baby:
            return j * r - baby[current]
    return -1


