from bisect import *
from copy import deepcopy
def compress(lst):
    '''
    B: lstを座圧したリスト
    idx_to_val: indexから元の値を取得するリスト
    val_to_idx: 元の値からindexを取得する辞書
    '''
    B = []
    val_to_idx = {}
    idx_to_val = deepcopy(lst)
    idx_to_val = list(set(idx_to_val))
    idx_to_val.sort()
    for i in range(len(lst)):
        ind = bisect_left(idx_to_val, lst[i])
        B.append(ind)
    for i in range(len(idx_to_val)):
        val_to_idx[idx_to_val[i]] = i
    return B, idx_to_val, val_to_idx


class Fenwick_Tree:
    def __init__(self, n):
        self._n = n
        self.data = [0] * n

    def add(self, p, x):
        assert 0 <= p < self._n
        p += 1
        while p <= self._n:
            self.data[p - 1] += x
            p += p & -p

    def sum(self, l, r):
        assert 0 <= l <= r <= self._n
        return self._sum(r) - self._sum(l)

    def _sum(self, r):
        s = 0
        while r > 0:
            s += self.data[r - 1]
            r -= r & -r
        return s

    # T.sum(0, x) <= kとなる最大のxを返す。
    def get(self, k):
        k += 1
        x, r = 0, 1
        while r < self._n:
            r <<= 1
        len = r
        while len:
            if x + len - 1 < self._n:
                if self.data[x + len - 1] < k:
                    k -= self.data[x + len - 1]
                    x += len
            len >>= 1
        return x

    def __str__(self):
        temp = []
        for i in range(self._n):
            temp.append(str(self.sum(i, i + 1)))
        return ' '.join(temp)



