    groups = [[] for _ in range(N)]
    for i in range(N):
        groups[comp[i]].append(i)
    for k in range(N):
        for j in range(len(groups[k])-1):
            uf.unite(groups[k][j], groups[k][j+1])

    new_constraints = []
    upd = False
    for a, b, c, d in constraints:
        ok = False
        if uf.same(a, c):
            upd = True
        orig_a = a
        orig_c = c
        while uf.same(a, c):
            if c >= d:
                print("No")
                exit()
            if a >= b:
                ok = True
                break
            a += 1
            c += 1
        if not ok:
            new_constraints.append((orig_a, b, orig_c, d))
    constraints = new_constraints

    if not upd:
        break

