            ind[x].append((y, z))
        tree = RangeDescendRangeMin(m)

        for x in ind:
            for y, z in ind[x]:
                if y:
                    pre = tree.range_min(0, y - 1)
                    if pre < z:
                        ac.st("Yes")
                        return
                if z:
                    pre = tree.range_min(0, z - 1)
                    if pre < y:
                        ac.st("Yes")
                        return
            for y, z in ind[x]:
                tree.range_descend(y, y, z)
                tree.range_descend(z, z, y)
        ac.st("No")
        return


